parameters.jsCode:
const body = $input.first().json.body;

if (!body || body.event !== 'messages.upsert' || !body.data) {
  return [];
}

const data = body.data;
const key = data.key || {};
const message = data.message || {};

if (key.fromMe === true) {
  return [];
}

let userText = '';
if (message.conversation) {
  userText = message.conversation;
} else if (message.extendedTextMessage && message.extendedTextMessage.text) {
  userText = message.extendedTextMessage.text;
}

if (!userText || !userText.trim()) {
  return [];
}

function formatPhone(p) {
  if (!p) return '';
  if (String(p).includes('@g.us')) return p;
  const c = String(p).replace(/\D/g, '');
  if (c.length === 10) return '57' + c;
  if (c.length === 12 && c.startsWith('57')) return c;
  return c;
}

const remoteJid = key.remoteJid || '';
const userPhone = remoteJid.includes('@g.us')
  ? remoteJid
  : formatPhone(remoteJid.replace('@s.whatsapp.net', ''));

const pushName = data.pushName || 'Cliente';
const instanceName = body.instance || 'default';
const trimmedText = userText.trim();

const match = trimmedText.match(/(aprobar|aprobas|aprobás|aprovar|cancelar|confirmar|rechazar)\s*([a-zA-Z0-9_-]{4,12})/i);
let isOwnerCommand = false;
let commandAction = '';
let commandCode = '';

if (match) {
  isOwnerCommand = true;
  const verb = match[1].toLowerCase();
  commandAction = (verb.includes('aprob') || verb === 'confirmar') ? 'confirmed' : 'cancelled';
  commandCode = match[2];
}

return [{
  json: {
    sessionId: userPhone,
    instance: instanceName,
    remoteJid: remoteJid,
    userPhone: userPhone,
    userName: pushName,
    messageText: trimmedText,
    isOwnerCommand: isOwnerCommand,
    commandAction: commandAction,
    commandCode: commandCode
  }
}];

