const res = $input.first().json;

function formatPhone(p) {
  if (!p) return '';
  if (String(p).includes('@g.us')) return p;
  const c = String(p).replace(/\D/g, '');
  if (c.length === 10) return '57' + c;
  if (c.length === 12 && c.startsWith('57')) return c;
  return c;
}

const ownerDestination = $('Normalize Incoming Message').item.json.userPhone;
const instance = $('Normalize Incoming Message').item.json.instance;

if (!res || res.success !== true) {
  return [{
    json: {
      toPhone: ownerDestination,
      instance: instance,
      message: '⚠️ No encontré esa reserva pendiente. Verifica el código e inténtalo de nuevo.',
      customerPhone: null,
      customerMessage: '',
      proofUrl: null
    }
  }];
}

const isConfirmed = res.status === 'confirmed';
const shortId = res.short_id || res.booking_id.slice(0, 6);
const booking = res.booking || {};
const proofUrl = booking.payment_proof_url || null;

const ownerMsg = isConfirmed
  ? `✅ *Reserva #${shortId} CONFIRMADA*\nCliente: ${res.customer_name}\n📅 ${res.date_str} ⏰ ${res.time_str}\n\n🎫 Ticket enviado al cliente.`
  : `❌ *Reserva #${shortId} CANCELADA*\nCliente: ${res.customer_name}\n\n📩 Cliente notificado.`;

let customerMsg = '';
if (res.customer_phone) {
  customerMsg = isConfirmed
    ? `🎟️ *TICKET DE RESERVA CONFIRMADA*\n\n🏟️ *${res.company_name}*\n⚽ Cancha: ${res.pitch_name}\n📅 Fecha: ${res.date_str}\n⏰ Hora: ${res.time_str}\n🎫 Ref: *#${shortId}*\n\nPresenta este ticket al llegar. ¡Que disfrutes el partido! 🏆`
    : `⚠️ Tu reserva (Ref: *#${shortId}*) en *${res.company_name}* no pudo ser confirmada.\n\nSi realizaste un pago, por favor comunícate con el establecimiento.`;
}

return [{
  json: {
    toPhone: ownerDestination,
    instance: instance,
    message: ownerMsg,
    customerPhone: formatPhone(res.customer_phone),
    customerMessage: customerMsg,
    proofUrl: proofUrl
  }
}];

